"use strict";(self.webpackChunklifewell_docs=self.webpackChunklifewell_docs||[]).push([["1385"],{26278(e){e.exports=JSON.parse('{"groups":[{"kind":"docs","key":"docs","pages":[{"permalink":"/intro","title":"LifeWell","description":"LifeWell keeps the people and moments of your life in one place \u2014 your family and friends, what you know about them, your memories and your plans, with wellbeing around them. Web and Android, kept by you.","tags":["overview","getting-started"]},{"permalink":"/plans","title":"Plans","description":"Free, Pro and Family \u2014 what each one includes, how Family seats work, how the free tier is drawn, and the two ways to pay. Prices in US dollars, monthly or yearly.","tags":["plans","account"]},{"permalink":"/admin","title":"The admin panel","description":"Ten screens, three roles, an audit log nobody can write to directly, and the controls that let plan limits and the referral programme change without a release.","tags":["admin"]},{"permalink":"/faq","title":"Questions people ask","description":"Answers to what people ask before trusting an app with a life \u2014 cost, privacy, getting your record out, offline use, and what LifeWell refuses to do.","tags":["faq"]}]},{"kind":"category","key":"/category/get-started","label":"Get started","pages":[{"permalink":"/category/get-started","title":"Get started with LifeWell","description":"Open it, sign in, and know what the first five screens are asking.","tags":[]},{"permalink":"/getting-started/install-web","title":"Use LifeWell on the web","description":"Open LifeWell in any current browser, sign in with Google, and start recording. No download, no account form, nothing to configure.","tags":["getting-started","web"]},{"permalink":"/getting-started/install-android","title":"Install on Android","description":"LifeWell on Android is a Capacitor build of the same app. Get it from Google Play, sign in with Google, and the record is the same one the web build reads.","tags":["getting-started","android"]},{"permalink":"/getting-started/first-run","title":"The first run","description":"What LifeWell asks the first time you sign in \u2014 five short steps, most of them skippable, and what each answer changes.","tags":["getting-started"]},{"permalink":"/getting-started/tour","title":"A short tour","description":"The dashboard, the menu, the top bar and the one control that changes how LifeWell looks \u2014 where things are before you go looking for them.","tags":["getting-started"]},{"permalink":"/getting-started/tours-and-walkthrough","title":"The page tour and the walkthrough","description":"Two ways to learn LifeWell \u2014 a short page tour from the signpost button in the top bar, and How LifeWell works, six screens with real screenshots. Plus the Jobs list for long tasks.","tags":["getting-started"]}]},{"kind":"category","key":"/domains/overview","label":"The seven areas","pages":[{"permalink":"/domains/overview","title":"The seven areas","description":"LifeWell is organised into seven areas around You \u2014 people first, then memories, everyday and sharing, with health, mind and life stages around them. Six can be switched off without deleting anything; Sharing cannot.","tags":["concepts","domains"]},{"permalink":"/domains/people","title":"People","description":"Where LifeWell starts \u2014 you, the people who matter, and what you know about them. Family and work trees, connections, places, messages, community, professionals and blood donation.","tags":["domains","people"]},{"permalink":"/domains/memories","title":"Memories","description":"Photos, albums, a scrapbook and the captions that make them readable \u2014 with the files themselves in your own Google Drive.","tags":["domains","memories"]},{"permalink":"/domains/everyday","title":"Everyday","description":"Calendar, appointments, notes, saved places, reminders and the shopping list \u2014 the ordinary week that holds the rest together.","tags":["domains","everyday"]},{"permalink":"/domains/sharing","title":"Sharing","description":"The only area with no switch. What a link can carry, who it is for, what the other person sees, how to end it, and what never leaves your record.","tags":["domains","sharing"]},{"permalink":"/domains/health","title":"Health","description":"Trackers, medications, food and meals, exercise and conditions \u2014 one area around the people in your life, there if you want it, and not the point of LifeWell.","tags":["domains","health"]},{"permalink":"/domains/mind","title":"Mind","description":"A journal, guided breathing and sleep sounds, mood, gratitude and desk wellness \u2014 kept where you can read them back, and never scored.","tags":["domains","mind"]},{"permalink":"/domains/stages","title":"Life stages","description":"Cycle, trying to conceive, ovulation, PCOS, menopause, pregnancy and a child\'s early years \u2014 the six screens one profile answer decides you see.","tags":["domains","stages"]}]},{"kind":"category","key":"/category/features","label":"Features","pages":[{"permalink":"/category/features","title":"Features","description":"The things that cut across more than one area.","tags":[]},{"permalink":"/features/calendar-and-appointments","title":"Calendar and appointments","description":"One calendar for the ordinary week and the medical one, with a checklist on each appointment for the questions you meant to ask.","tags":["features","everyday"]},{"permalink":"/features/reminders","title":"Reminders","description":"What LifeWell may send you, when, and on which device \u2014 three master switches, quiet hours, and why the app never asks Android for an exact alarm.","tags":["features","everyday"]},{"permalink":"/features/search","title":"Search","description":"One search across your whole record. The server half is built; the page is not finished yet, and the app says so rather than showing an empty result list.","tags":["features"]},{"permalink":"/features/community-and-chats","title":"Community and chats","description":"Groups with posts and replies, one-to-one messages between connected accounts, blocking, and a moderation route that never tells an author who reported them.","tags":["features","people"]},{"permalink":"/features/professionals","title":"Professionals","description":"A directory of practitioners who listed themselves. LifeWell does not check anyone\'s qualifications \u2014 it prints the registration number and links to the register so you can check it yourself.","tags":["features","people"]},{"permalink":"/features/blood-donation","title":"Blood donation","description":"A public directory of donors, requests that reach them, and a contact release that is given once to one person and can be withdrawn.","tags":["features","people"]},{"permalink":"/features/referrals","title":"The referral programme","description":"Invite someone, and a confirmed sign-up earns points, a badge and \u2014 past a threshold \u2014 a month of a paid plan. Every number is an admin setting rather than a constant.","tags":["features","plans"]},{"permalink":"/features/shopping-list","title":"The shopping list","description":"A list built from your meals and recipes or written by hand, and shared as plain text so the person doing the shop needs no account.","tags":["features","everyday","health"]},{"permalink":"/features/maps","title":"Maps and places","description":"Your own record plotted where it happened \u2014 memories, notes, people and events \u2014 plus saved places and an opt-in location history.","tags":["features","people","memories"]},{"permalink":"/features/tools","title":"Tools and calculators","description":"Which calculators live in LifeWell, which live on ZTools, and why the tools directory is mostly a set of links rather than re-implementations.","tags":["features","tools"]}]},{"kind":"category","key":"/category/your-data","label":"Your data","pages":[{"permalink":"/category/your-data","title":"Your data","description":"Getting it out, getting rid of it, and knowing where it is.","tags":[]},{"permalink":"/your-data/export","title":"Export everything","description":"Take your whole record out of LifeWell as JSON, CSV or PDF. The file is built on your device, and the format is documented field by field.","tags":["your-data","export"]},{"permalink":"/your-data/delete","title":"Delete your record","description":"Delete your whole account, or one of the seven areas and keep the rest. What each one removes, what it deliberately keeps, and where each stands today.","tags":["your-data","privacy"]},{"permalink":"/your-data/where-it-lives","title":"Where your record lives","description":"Written on your device first, synced to a Postgres database with per-row rules, with photos in your own Google Drive. What that means when you go offline, disconnect, or leave.","tags":["your-data","privacy","concepts"]}]},{"kind":"category","key":"/category/how-it-works","label":"How it works","pages":[{"permalink":"/category/how-it-works","title":"How it works","description":"Architecture, the data model, privacy, offline behaviour and appearance.","tags":[]},{"permalink":"/concepts/architecture","title":"Architecture","description":"A static single-page app over Postgres, with edge functions only where the browser must not hold something. What runs where, and why there is no server of our own.","tags":["concepts","architecture"]},{"permalink":"/concepts/data-model","title":"The data model","description":"How LifeWell stores a life \u2014 one table per idea, one store behind every tracker, and the three decisions that shape everything above them.","tags":["concepts","architecture"]},{"permalink":"/concepts/privacy-and-security","title":"Privacy and security","description":"What leaves your device and what does not \u2014 sign-in without a password, per-row database rules, scrubbed analytics, the contacts permission, identity card pictures, and the claims LifeWell deliberately does not make.","tags":["concepts","privacy"]},{"permalink":"/concepts/offline-and-sync","title":"Offline and sync","description":"Entries are written locally first and sync when there is a connection. What works with no signal, what does not, and how the app says which.","tags":["concepts","offline"]},{"permalink":"/concepts/appearance","title":"Appearance","description":"One icon, one panel, nine settings \u2014 theme, colour, corner radius, density, text size, typeface, surface style, motion and pointer. Applied before the first paint.","tags":["concepts","appearance"]},{"permalink":"/concepts/language-and-units","title":"Language and units","description":"English is the only language today, and the app is built so a second one is a single new file. Units are a preference, not a consequence of your language.","tags":["concepts","i18n","accessibility"]}]},{"kind":"category","key":"/category/platforms","label":"Platforms","pages":[{"permalink":"/category/platforms","title":"Platforms","description":"Web, Android, and the two that do not exist.","tags":[]},{"permalink":"/platforms/web","title":"Web","description":"The web build is the reference build \u2014 everything LifeWell does, apart from the two things Android delivers through the operating system.","tags":["platforms","web"]},{"permalink":"/platforms/android","title":"Android","description":"LifeWell on Android \u2014 minimum Android 9, every permission the app declares and why each one is there, local reminders, and the two things that are built but not switched on.","tags":["platforms","android"]},{"permalink":"/platforms/ios","title":"iOS","description":"iOS was removed from LifeWell on 2026-07-16. It will be re-added when an Apple Developer account exists, and not before.","tags":["platforms","ios"]},{"permalink":"/platforms/browser-extension","title":"Browser extension","description":"A LifeWell browser extension is planned and not built. Nothing is published, and there is nothing to install today.","tags":["platforms","extension"]}]},{"kind":"category","key":"/category/reference","label":"Reference","pages":[{"permalink":"/category/reference","title":"Reference","description":"The export file format, the frozen addresses, and every outside service.","tags":[]},{"permalink":"/reference/export-format","title":"The export file format","description":"What is in a LifeWell export, field by field and table by table \u2014 the JSON header, the CSV archive, what the PDF leaves out, and what no format ever contains.","tags":["reference","export","your-data"]},{"permalink":"/reference/addresses","title":"Addresses that do not move","description":"Ninety-nine public LifeWell addresses and fifteen redirects that are frozen. A rebuild changes code, not addresses.","tags":["reference","seo"]},{"permalink":"/reference/integrations","title":"Third-party services","description":"Every outside service LifeWell talks to, what it is for, what it receives, and what happens when its key is absent.","tags":["reference","privacy"]}]},{"kind":"category","key":"/about/the-developer","label":"About","pages":[{"permalink":"/about/the-developer","title":"Who builds LifeWell","description":"LifeWell is built and maintained by the LifeWell team, and the product is direct about what it cannot do.","tags":["about"]},{"permalink":"/about/changelog","title":"Changelog","description":"LifeWell 3.0 (version string 3.22.0) is a full rebuild on a new backend, and 3.23 to 3.25 followed in October 2026. What is new, what was removed, what was corrected, and the reset that comes with 3.0.","tags":["about","changelog"]},{"permalink":"/about/contributing","title":"Contributing to these docs","description":"How to correct a page, what belongs here, and the one rule that matters \u2014 this documentation may only describe what the product actually does.","tags":["about"]}]}],"blog":{"permalink":"/blog","title":"Blog","description":"Updates and release notes from the LifeWell team: what changed in the app, and why.","tags":[]},"posts":[{"permalink":"/blog/documentation-rewritten-for-3-0-0","title":"The documentation was wrong, so it was rewritten","description":"LifeWell 3.0.0 is a rebuild on a new backend, and the old documentation described a product that no longer exists. Every page was deleted and rewritten against the code.","tags":["Announcement","LifeWell","Docs","Release"],"date":"2026-09-08"}]}')}}]);